                    'Deposit', 'Credit Received',
                    'Withdrawal', 'OMC Online Transfer', 'Bank Fee', 'Owner Transfer',
                    'Vendor Payment', 'Expense Payment')),
  amount          numeric not null check (amount > 0),
  deposit_slip_no text,
  description     text not null default '',
  source_type     text,
  source_id       text,
