-- manual ledger corrections: Debit = customer owes more, Credit = customer owes less
create table if not exists public.s02_customer_adjustments (
  id           text primary key,
  date         date not null,
  customer_id  text not null references public.s02_customers(id) on delete restrict,
  kind         text not null check (kind in ('Debit', 'Credit')),
