-- ---- updated_at triggers ------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array[
    's02_station_settings', 's02_tanks', 's02_nozzles', 's02_fuel_sales', 's02_shifts', 's02_tank_dips',
    's02_omc_invoices', 's02_omc_payments', 's02_bank_accounts', 's02_bank_transactions', 's02_owner_transfers',
    's02_daybook_entries', 's02_customers', 's02_credit_slips', 's02_customer_recoveries', 's02_customer_adjustments',
    's02_expenses', 's02_staff_members', 's02_staff_advances', 's02_staff_salary_payments',
    's02_lubricant_products', 's02_lubricant_movements', 's02_suppliers', 's02_supplier_transactions',
    's02_tariff_revisions'
  ] loop
    execute format('drop trigger if exists set_updated_at on public.%I', t);
    execute format('create trigger set_updated_at before update on public.%I for each row execute function public.tg_set_updated_at()', t);
  end loop;
end $$;

-- =========================================================================
-- ROW LEVEL SECURITY for 'SITE-02'
--   owner / manager : read + write everything of this station
--   cashier         : read forecourt reference data; INSERT operational records;
--                     cannot edit/delete, cannot see banking, payroll, suppliers, OMC
--   anonymous       : nothing
-- =========================================================================
do $$
declare
  t   text;
  pol record;
  ops_tables text[] := array[
    's02_fuel_sales', 's02_tank_dips', 's02_daybook_entries', 's02_credit_slips',
    's02_customer_recoveries', 's02_expenses', 's02_lubricant_movements'
  ];
  ref_tables text[] := array[
    's02_station_settings', 's02_tanks', 's02_nozzles', 's02_customers', 's02_customer_adjustments',
    's02_lubricant_products', 's02_bank_accounts', 's02_shifts'
  ];
  mgr_tables text[] := array[
    's02_omc_invoices', 's02_omc_payments', 's02_bank_transactions', 's02_owner_transfers',
    's02_staff_members', 's02_staff_advances', 's02_staff_salary_payments',
    's02_suppliers', 's02_supplier_transactions', 's02_tariff_revisions'
  ];
begin
  foreach t in array ops_tables || ref_tables || mgr_tables || array['s02_audit_log', 's02_doc_counters'] loop
    execute format('alter table public.%I enable row level security', t);
    for pol in select policyname from pg_policies where schemaname = 'public' and tablename = t loop
      execute format('drop policy %I on public.%I', pol.policyname, t);
    end loop;
  end loop;

  foreach t in array ops_tables loop
    execute format('create policy p_select on public.%I for select to authenticated using (public.has_site_access(''SITE-02''))', t);
    execute format('create policy p_insert on public.%I for insert to authenticated with check (public.has_site_access(''SITE-02''))', t);
    execute format('create policy p_update on public.%I for update to authenticated using (public.is_site_manager(''SITE-02'')) with check (public.is_site_manager(''SITE-02''))', t);
    execute format('create policy p_delete on public.%I for delete to authenticated using (public.is_site_manager(''SITE-02''))', t);
  end loop;

  foreach t in array ref_tables loop
    execute format('create policy p_select on public.%I for select to authenticated using (public.has_site_access(''SITE-02''))', t);
    execute format('create policy p_insert on public.%I for insert to authenticated with check (public.is_site_manager(''SITE-02''))', t);
    execute format('create policy p_update on public.%I for update to authenticated using (public.is_site_manager(''SITE-02'')) with check (public.is_site_manager(''SITE-02''))', t);
    execute format('create policy p_delete on public.%I for delete to authenticated using (public.is_site_manager(''SITE-02''))', t);
  end loop;

  foreach t in array mgr_tables loop
    execute format('create policy p_select on public.%I for select to authenticated using (public.is_site_manager(''SITE-02''))', t);
    execute format('create policy p_insert on public.%I for insert to authenticated with check (public.is_site_manager(''SITE-02''))', t);
    execute format('create policy p_update on public.%I for update to authenticated using (public.is_site_manager(''SITE-02'')) with check (public.is_site_manager(''SITE-02''))', t);
    execute format('create policy p_delete on public.%I for delete to authenticated using (public.is_site_manager(''SITE-02''))', t);
  end loop;

  -- audit log: anyone at the station appends, only managers read, nobody edits
  create policy p_insert on public.s02_audit_log for insert to authenticated with check (public.has_site_access('SITE-02'));
  create policy p_select on public.s02_audit_log for select to authenticated using (public.is_site_manager('SITE-02'));
  -- s02_doc_counters: RLS on, no policy => reachable only through next_doc_no()
end $$;

-- ---- privileges ----------------------------------------------------------
do $$
declare t text;
begin
  for t in select tablename from pg_tables where schemaname = 'public' and tablename like 's02\_%' loop
    execute format('revoke all on public.%I from anon', t);
    execute format('grant select, insert, update, delete on public.%I to authenticated', t);
  end loop;
end $$;
revoke all on public.s02_doc_counters from authenticated;

-- ---- realtime (live multi-device sync) -----------------------------------
do $$
declare t text;
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    for t in
      select tablename from pg_tables
       where schemaname = 'public' and tablename like 's02\_%'
         and tablename not in ('s02_doc_counters', 's02_audit_log')
    loop
      if not exists (
        select 1 from pg_publication_tables
         where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t
      ) then
        execute format('alter publication supabase_realtime add table public.%I', t);
      end if;
    end loop;
  end if;
end $$;

-- =========================================================================
-- PART 4 — POLICIES FOR THE SHARED TABLES
-- (per-station tables get their own policies from the station template)
-- =========================================================================

alter table public.stations         enable row level security;
alter table public.profiles         enable row level security;
alter table public.profile_stations enable row level security;
alter table public.migration_log    enable row level security;

do $$
declare pol record;
begin
  for pol in
    select tablename, policyname from pg_policies
     where schemaname = 'public' and tablename in ('stations', 'profiles', 'profile_stations', 'migration_log')
  loop
    execute format('drop policy %I on public.%I', pol.policyname, pol.tablename);
  end loop;
end $$;

-- public station list (name / brand / location) — needed on the "choose a station" screen
create policy p_select_public on public.stations for select to anon, authenticated using (true);
-- managers may edit the profile of their own station
create policy p_update on public.stations for update to authenticated
  using (public.is_site_manager(site_id)) with check (public.is_site_manager(site_id));

-- a user reads only their own profile and station assignments (admin_* functions do the rest)
create policy p_select_own on public.profiles         for select to authenticated using (user_id = auth.uid());
create policy p_select_own on public.profile_stations for select to authenticated using (user_id = auth.uid());
-- migration_log: RLS on, no policy => invisible to the app

revoke all on public.stations, public.profiles, public.profile_stations, public.migration_log from anon, authenticated;
grant select on public.stations to anon;
grant select, update on public.stations to authenticated;
grant select on public.profiles, public.profile_stations to authenticated;

-- the old (archived) tables must never be readable through the public API
do $$
declare t text;
begin
  foreach t in array array[
    'legacy_stations', 'legacy_fuel_sales', 'legacy_tank_dips', 'legacy_daybook_vouchers',
    'legacy_credit_fuel_slips', 'legacy_customer_recoveries', 'legacy_omc_invoices',
    'legacy_tariff_revisions', 'legacy_owner_transfers'
  ] loop
    if to_regclass('public.' || t) is not null then
      execute format('revoke all on public.%I from anon, authenticated', t);
    end if;
  end loop;
end $$;

-- =========================================================================
-- DATA MIGRATION for 'SITE-01' -> tables s01_*
-- -------------------------------------------------------------------------
-- Source 1: the old JSON snapshot   (legacy_stations.data)         — authoritative
-- Source 2: the old side tables     (legacy_fuel_sales, ...)       — any record that is
--           NOT in the snapshot is recovered too (a stale browser could overwrite
--           the snapshot and silently drop records that had already reached these tables).
-- Nothing is deleted from the archive. Re-running is safe (guarded by migration_log,
-- and every insert is ON CONFLICT DO NOTHING).
--
-- Balances are converted to "opening balance + transactions" so that every
-- balance shown before the migration is identical after it:
--   customer opening  = old balance - snapshot slips + snapshot recoveries
--   bank opening      = old balance - signed snapshot bank transactions
--   supplier opening  = old balance due
--   lube opening      = old stock
--   OMC invoice       = old paid amount - snapshot payments
--   tank / nozzle     = old level / old meter reading
-- =========================================================================
do $mig$
declare
  v_site   constant text := 'SITE-01';
  d        jsonb;
  leg      jsonb;
  v_rec    jsonb;
  v_log    jsonb := '{}'::jsonb;
  n        int;
begin
  if exists (select 1 from public.migration_log where name = 'legacy-import:' || v_site) then
    raise notice '[%] legacy import already done - skipping', v_site;
    return;
  end if;

  if to_regclass('public.legacy_stations') is not null then
    execute 'select ls.data from public.legacy_stations ls where ls.site_id = $1' into d using v_site;
  end if;
  if d is null then
    insert into public.migration_log (name, details) values ('legacy-import:' || v_site, '{"note":"no legacy snapshot found"}');
    return;
  end if;

  -- ---- station profile & settings ---------------------------------------
  update public.stations s set
    code         = coalesce(d->'siteInfo'->>'code', s.code),
    name         = coalesce(d->'siteInfo'->>'name', s.name),
    location     = coalesce(d->'siteInfo'->>'location', s.location),
    brand        = coalesce(d->'siteInfo'->>'brand', s.brand),
    brand_color  = coalesce(d->'siteInfo'->>'brandColor', s.brand_color),
    phone        = coalesce(d->'siteInfo'->>'phone', s.phone),
    manager_name = coalesce(d->'siteInfo'->>'managerName', s.manager_name),
    ntn          = coalesce(d->'siteInfo'->>'ntn', s.ntn)
  where s.site_id = v_site;

  update public.s01_station_settings set
    rate_pmg            = coalesce((d->'settings'->'rates'->>'PMG Super')::numeric, rate_pmg),
    rate_hsd            = coalesce((d->'settings'->'rates'->>'HSD Diesel')::numeric, rate_hsd),
    rate_octane         = coalesce((d->'settings'->'rates'->>'Hi-Octane')::numeric, rate_octane),
    station_phone       = coalesce(d->'settings'->>'stationPhone', station_phone),
    manager_contact     = coalesce(d->'settings'->>'managerContact', manager_contact),
    receipt_header      = coalesce(d->'settings'->>'receiptHeader', receipt_header),
    receipt_footer      = coalesce(d->'settings'->>'receiptFooter', receipt_footer),
    low_stock_alert_pct = coalesce((d->'settings'->>'lowStockAlertPct')::numeric, low_stock_alert_pct),
    cash_difference_alert_limit = coalesce((d->'settings'->>'cashDifferenceAlertLimit')::numeric, cash_difference_alert_limit)
  where id = 'main';

  -- ---- tanks & nozzles ---------------------------------------------------
  insert into public.s01_tanks (id, tank_no, fuel_type, capacity_liters, min_reserve_liters, initial_liters, initial_dip_mm)
  select t->>'id', (t->>'tankNo')::int, t->>'fuelType', (t->>'capacityLiters')::numeric,
         coalesce((t->>'minReserveLiters')::numeric, 0),
         coalesce((t->>'currentLiters')::numeric, 0), coalesce((t->>'currentDipMm')::numeric, 0)
    from jsonb_array_elements(coalesce(d->'tanks', '[]')) t
  on conflict do nothing;

  insert into public.s01_nozzles (id, tank_id, dispenser_no, nozzle_no, initial_meter, testing_liters, assigned_staff, is_active)
  select z->>'id', z->>'tankId', (z->>'dispenserNo')::int, (z->>'nozzleNo')::int,
         greatest(coalesce((z->>'closingMeter')::numeric, 0), coalesce((z->>'openingMeter')::numeric, 0)),
         coalesce((z->>'testingLiters')::numeric, 0), coalesce(z->>'assignedStaff', ''), true
    from jsonb_array_elements(coalesce(d->'nozzles', '[]')) z
  on conflict do nothing;

  -- ---- shifts & fuel sales ------------------------------------------------
  insert into public.s01_shifts (id, shift_name, date, incharge, status, start_time, end_time, total_fuel_sales,
      total_lube_sales, credit_sales, digital_payments, shift_expenses, credit_recoveries, expected_cash,
      actual_cash, shortage_excess, notes, created_at)
  select r->>'id', coalesce(r->>'shiftName', 'Morning'), coalesce(nullif(r->>'date','')::date, current_date),
         coalesce(r->>'incharge', ''), coalesce(r->>'status', 'Closed'), coalesce(r->>'startTime', ''), coalesce(r->>'endTime', ''),
         coalesce((r->>'totalFuelSales')::numeric, 0), coalesce((r->>'totalLubeSales')::numeric, 0),
         coalesce((r->>'creditSales')::numeric, 0), coalesce((r->>'digitalPayments')::numeric, 0),
         coalesce((r->>'shiftExpenses')::numeric, 0), coalesce((r->>'creditRecoveries')::numeric, 0),
         coalesce((r->>'expectedCash')::numeric, 0), coalesce((r->>'actualCash')::numeric, 0),
         coalesce((r->>'shortageExcess')::numeric, 0), r->>'notes',
         (coalesce(nullif(r->>'date','')::date, current_date) + time '12:00')::timestamptz
    from jsonb_array_elements(coalesce(d->'shifts', '[]')) r
  on conflict do nothing;

  insert into public.s01_fuel_sales (id, date, shift_name, shift_id, nozzle_id, dispenser_no, nozzle_no, fuel_type,
      opening_meter, closing_meter, testing_liters, net_liters, rate_per_liter, total_amount, cashier_name, created_at)
  select r->>'id', coalesce(nullif(r->>'date','')::date, current_date),
         coalesce((select sh->>'shiftName' from jsonb_array_elements(coalesce(d->'shifts','[]')) sh where sh->>'id' = r->>'shiftId' limit 1), 'Morning'),
         r->>'shiftId', r->>'nozzleId', coalesce((r->>'dispenserNo')::int, 0), coalesce((r->>'nozzleNo')::int, 0),
         r->>'fuelType', (r->>'openingMeter')::numeric, greatest((r->>'closingMeter')::numeric, (r->>'openingMeter')::numeric),
         coalesce((r->>'testingLiters')::numeric, 0), greatest(coalesce((r->>'netLiters')::numeric, 0), 0),
         (r->>'ratePerLiter')::numeric, (r->>'totalAmount')::numeric, coalesce(r->>'cashierName', ''),
         (coalesce(nullif(r->>'date','')::date, current_date) + time '12:00')::timestamptz
    from jsonb_array_elements(coalesce(d->'fuelSales', '[]')) r
  on conflict do nothing;

  -- side-table sales that are not in the snapshot
  if to_regclass('public.legacy_fuel_sales') is not null then
    execute 'select coalesce(jsonb_agg(to_jsonb(l) order by l.created_at), ''[]''::jsonb) from public.legacy_fuel_sales l where l.site_id = $1'
      into leg using v_site;
    insert into public.s01_fuel_sales (id, date, shift_name, nozzle_id, dispenser_no, nozzle_no, fuel_type,
        opening_meter, closing_meter, testing_liters, net_liters, rate_per_liter, total_amount, cashier_name, created_at)
    select r->>'id', (r->>'date')::date, coalesce(r->>'shift', 'Morning'), r->>'nozzle_id',
           coalesce((select nz.dispenser_no from public.s01_nozzles nz where nz.id = r->>'nozzle_id'), 0),
           coalesce((select nz.nozzle_no from public.s01_nozzles nz where nz.id = r->>'nozzle_id'), 0),
           r->>'fuel_type', (r->>'start_meter')::numeric, greatest((r->>'end_meter')::numeric, (r->>'start_meter')::numeric),
           0, (r->>'liters_sold')::numeric, (r->>'rate')::numeric, (r->>'amount')::numeric,
           coalesce(r->>'recorded_by', ''), coalesce((r->>'created_at')::timestamptz, now())
      from jsonb_array_elements(leg) r
    on conflict do nothing;
    get diagnostics n = row_count;
    v_log := v_log || jsonb_build_object('recovered_fuel_sales', n);
  end if;

  -- ---- tank dips ---------------------------------------------------------
  insert into public.s01_tank_dips (id, date, tank_id, tank_no, fuel_type, morning_dip_mm, morning_liters, decanted_liters,
      dispensed_liters, book_stock_liters, closing_dip_mm, closing_physical_liters, variance_liters, water_dip_mm, inspector, created_at)
  select r->>'id', coalesce(nullif(r->>'date','')::date, current_date), r->>'tankId', (r->>'tankNo')::int, r->>'fuelType',
         coalesce((r->>'morningDipMm')::numeric, 0), coalesce((r->>'morningLiters')::numeric, 0),
         coalesce((r->>'decantedLiters')::numeric, 0), coalesce((r->>'dispensedLiters')::numeric, 0),
         coalesce((r->>'bookStockLiters')::numeric, 0), coalesce((r->>'closingDipMm')::numeric, 0),
         coalesce((r->>'closingPhysicalLiters')::numeric, 0), coalesce((r->>'varianceLiters')::numeric, 0),
         coalesce((r->>'waterDipMm')::numeric, 0), coalesce(r->>'inspector', ''),
         (coalesce(nullif(r->>'date','')::date, current_date) + time '12:00')::timestamptz
    from jsonb_array_elements(coalesce(d->'tankDips', '[]')) r
   where exists (select 1 from public.s01_tanks tk where tk.id = r->>'tankId')
  on conflict do nothing;

  if to_regclass('public.legacy_tank_dips') is not null then
    execute 'select coalesce(jsonb_agg(to_jsonb(l) order by l.created_at), ''[]''::jsonb) from public.legacy_tank_dips l where l.site_id = $1'
      into leg using v_site;
    insert into public.s01_tank_dips (id, date, tank_id, tank_no, fuel_type, morning_dip_mm, morning_liters, decanted_liters,
        dispensed_liters, book_stock_liters, closing_dip_mm, closing_physical_liters, variance_liters, water_dip_mm, inspector, created_at)
    select r->>'id', (r->>'date')::date, r->>'tank_id', (r->>'tank_no')::int, r->>'fuel_type',
           coalesce((r->>'opening_dip_mm')::numeric, 0), coalesce((r->>'opening_liters')::numeric, 0), 0,
           coalesce((r->>'sales_during_shift')::numeric, 0), coalesce((r->>'expected_liters')::numeric, 0),
           coalesce((r->>'closing_dip_mm')::numeric, 0), (r->>'closing_physical_liters')::numeric,
           coalesce((r->>'variance_liters')::numeric, 0), 0, coalesce(r->>'recorded_by', ''),
           coalesce((r->>'created_at')::timestamptz, now())
      from jsonb_array_elements(leg) r
     where exists (select 1 from public.s01_tanks tk where tk.id = r->>'tank_id')
    on conflict do nothing;
    get diagnostics n = row_count;
    v_log := v_log || jsonb_build_object('recovered_tank_dips', n);
  end if;

  -- ---- OMC invoices & payments -------------------------------------------
  insert into public.s01_omc_invoices (id, invoice_no, date, brand, tank_lorry_no, driver_name, fuel_type,
      invoice_volume_liters, decanted_volume_liters, rate_per_liter, freight_amount, total_amount, opening_paid_amount, created_at)
  select r->>'id', r->>'invoiceNo', coalesce(nullif(r->>'date','')::date, current_date), coalesce(r->>'brand', ''),
         coalesce(r->>'tankLorryNo', ''), coalesce(r->>'driverName', ''), r->>'fuelType',
         coalesce((r->>'invoiceVolumeLiters')::numeric, 0), coalesce((r->>'decantedVolumeLiters')::numeric, 0),
         coalesce((r->>'ratePerLiter')::numeric, 0), coalesce((r->>'freightAmount')::numeric, 0),
         coalesce((r->>'totalAmount')::numeric, 0),
         coalesce((r->>'paidAmount')::numeric, 0)
           - coalesce((select sum((p->>'amount')::numeric) from jsonb_array_elements(coalesce(d->'omcPayments','[]')) p
                        where p->>'invoiceNo' = r->>'invoiceNo'), 0),
         (coalesce(nullif(r->>'date','')::date, current_date) + time '12:00')::timestamptz
    from jsonb_array_elements(coalesce(d->'omcInvoices', '[]')) r
  on conflict do nothing;

  insert into public.s01_omc_payments (id, date, invoice_no, payment_method, bank_name, reference_no, amount, recorded_by, created_at)
  select r->>'id', coalesce(nullif(r->>'date','')::date, current_date), r->>'invoiceNo',
         coalesce(r->>'paymentMethod', 'Bank Transfer'), coalesce(r->>'bankName', ''), coalesce(r->>'referenceNo', ''),
         (r->>'amount')::numeric, coalesce(r->>'recordedBy', ''),
         (coalesce(nullif(r->>'date','')::date, current_date) + time '12:00')::timestamptz
    from jsonb_array_elements(coalesce(d->'omcPayments', '[]')) r
   where (r->>'amount')::numeric > 0
  on conflict do nothing;

  if to_regclass('public.legacy_omc_invoices') is not null then
    execute 'select coalesce(jsonb_agg(to_jsonb(l) order by l.created_at), ''[]''::jsonb) from public.legacy_omc_invoices l where l.site_id = $1'
      into leg using v_site;
    insert into public.s01_omc_invoices (id, invoice_no, date, brand, fuel_type, invoice_volume_liters, decanted_volume_liters,
        rate_per_liter, total_amount, opening_paid_amount, created_at)
    select r->>'id', r->>'invoice_no', (r->>'date')::date, coalesce(r->>'omc_name', ''), r->>'fuel_type',
           coalesce((r->>'liters')::numeric, 0), coalesce((r->>'liters')::numeric, 0), coalesce((r->>'product_rate')::numeric, 0),
           (r->>'total_amount')::numeric, coalesce((r->>'paid_amount')::numeric, 0),
           coalesce((r->>'created_at')::timestamptz, now())
      from jsonb_array_elements(leg) r
     where not exists (select 1 from public.s01_omc_invoices i where i.invoice_no = r->>'invoice_no')
    on conflict do nothing;
    get diagnostics n = row_count;
    v_log := v_log || jsonb_build_object('recovered_omc_invoices', n);
  end if;

  -- ---- banking -------------------------------------------------------------
  insert into public.s01_bank_accounts (id, bank_name, account_title, account_number, branch, opening_balance)
  select b->>'id', b->>'bankName', coalesce(b->>'accountTitle', ''), coalesce(b->>'accountNumber', ''), coalesce(b->>'branch', ''),
         coalesce((b->>'currentBalance')::numeric, 0)
           - coalesce((select sum(case when x->>'type' in ('Deposit') then (x->>'amount')::numeric else -(x->>'amount')::numeric end)
                         from jsonb_array_elements(coalesce(d->'bankTransactions','[]')) x where x->>'bankId' = b->>'id'), 0)
    from jsonb_array_elements(coalesce(d->'bankAccounts', '[]')) b
  on conflict do nothing;

  insert into public.s01_bank_transactions (id, bank_id, date, type, amount, deposit_slip_no, description, created_at)
  select x->>'id', x->>'bankId', coalesce(nullif(x->>'date','')::date, current_date), x->>'type', (x->>'amount')::numeric,
         x->>'depositSlipNo', coalesce(x->>'description', ''),
         (coalesce(nullif(x->>'date','')::date, current_date) + time '12:00')::timestamptz
    from jsonb_array_elements(coalesce(d->'bankTransactions', '[]')) x
   where (x->>'amount')::numeric > 0
     and exists (select 1 from public.s01_bank_accounts ba where ba.id = x->>'bankId')
  on conflict do nothing;

  insert into public.s01_owner_transfers (id, date, amount, bank_id, bank_name, account_title, account_number, reference_no,
      status, notes, transferred_by, created_at)
  select r->>'id', coalesce(nullif(r->>'date','')::date, current_date), (r->>'amount')::numeric, coalesce(r->>'bankId', ''),
         coalesce(r->>'bankName', ''), coalesce(r->>'accountTitle', ''), coalesce(r->>'accountNumber', ''),
         coalesce(r->>'referenceNo', ''), coalesce(r->>'status', 'Completed'), r->>'notes', coalesce(r->>'transferredBy', ''),
         (coalesce(nullif(r->>'date','')::date, current_date) + time '12:00')::timestamptz
    from jsonb_array_elements(coalesce(d->'ownerTransfers', '[]')) r
   where (r->>'amount')::numeric > 0
  on conflict do nothing;

  -- ---- customers, slips, recoveries --------------------------------------
  insert into public.s01_customers (id, name, business_name, phone, vehicle_numbers, credit_limit, opening_balance, status)
  select c->>'id', coalesce(c->>'name', c->>'businessName'), coalesce(c->>'businessName', c->>'name'), coalesce(c->>'phone', ''),
         coalesce(array(select jsonb_array_elements_text(coalesce(c->'vehicleNumbers', '[]'))), '{}'),
         coalesce((c->>'creditLimit')::numeric, 0),
         coalesce((c->>'currentBalance')::numeric, 0)
           - coalesce((select sum((s->>'totalAmount')::numeric) from jsonb_array_elements(coalesce(d->'creditSlips','[]')) s where s->>'customerId' = c->>'id'), 0)
           + coalesce((select sum((r->>'amount')::numeric) from jsonb_array_elements(coalesce(d->'recoveries','[]')) r where r->>'customerId' = c->>'id'), 0),
         case when c->>'status' = 'Hold' then 'Hold' else 'Active' end
    from jsonb_array_elements(coalesce(d->'customers', '[]')) c
  on conflict do nothing;

  insert into public.s01_credit_slips (id, slip_no, date, customer_id, customer_name, vehicle_no, driver_name, fuel_type,
      liters, rate, total_amount, authorized_by, created_at)
  select s->>'id', s->>'slipNo', coalesce(nullif(s->>'date','')::date, current_date), s->>'customerId', coalesce(s->>'customerName', ''),
         coalesce(s->>'vehicleNo', ''), coalesce(s->>'driverName', ''), s->>'fuelType',
         greatest((s->>'liters')::numeric, 0.001), coalesce((s->>'rate')::numeric, 0), coalesce((s->>'totalAmount')::numeric, 0),
         coalesce(s->>'authorizedBy', ''), (coalesce(nullif(s->>'date','')::date, current_date) + time '12:00')::timestamptz
    from jsonb_array_elements(coalesce(d->'creditSlips', '[]')) s
   where exists (select 1 from public.s01_customers cu where cu.id = s->>'customerId')
  on conflict do nothing;

  insert into public.s01_customer_recoveries (id, receipt_no, date, customer_id, customer_name, payment_method, amount,
      reference_no, received_by, created_at)
  select r->>'id', r->>'receiptNo', coalesce(nullif(r->>'date','')::date, current_date), r->>'customerId', coalesce(r->>'customerName', ''),
         coalesce(r->>'paymentMethod', 'Cash'), (r->>'amount')::numeric, coalesce(r->>'referenceNo', ''), coalesce(r->>'receivedBy', ''),
         (coalesce(nullif(r->>'date','')::date, current_date) + time '12:00')::timestamptz
    from jsonb_array_elements(coalesce(d->'recoveries', '[]')) r
   where (r->>'amount')::numeric > 0
     and exists (select 1 from public.s01_customers cu where cu.id = r->>'customerId')
  on conflict do nothing;

  -- side-table credit slips / recoveries that are not in the snapshot.
  -- (Their amounts are ADDED on top of the snapshot-based opening balance, i.e. they raise/lower the customer's due.)
  if to_regclass('public.legacy_credit_fuel_slips') is not null then
    execute 'select coalesce(jsonb_agg(to_jsonb(l) order by l.created_at), ''[]''::jsonb) from public.legacy_credit_fuel_slips l where l.site_id = $1'
      into leg using v_site;
    insert into public.s01_credit_slips (id, slip_no, date, customer_id, customer_name, vehicle_no, driver_name, fuel_type,
        liters, rate, total_amount, authorized_by, created_at)
    select r->>'id', r->>'slip_no', (r->>'date')::date, r->>'customer_id', coalesce(r->>'customer_name', ''),
           coalesce(r->>'vehicle_no', ''), coalesce(r->>'driver_name', ''), r->>'fuel_type', (r->>'liters')::numeric,
           (r->>'rate')::numeric, (r->>'total_amount')::numeric, coalesce(r->>'authorized_by', ''),
           coalesce((r->>'created_at')::timestamptz, now())
      from jsonb_array_elements(leg) r
     where exists (select 1 from public.s01_customers cu where cu.id = r->>'customer_id')
    on conflict do nothing;
    get diagnostics n = row_count;
    v_log := v_log || jsonb_build_object('recovered_credit_slips', n);
  end if;

  if to_regclass('public.legacy_customer_recoveries') is not null then
    execute 'select coalesce(jsonb_agg(to_jsonb(l) order by l.created_at), ''[]''::jsonb) from public.legacy_customer_recoveries l where l.site_id = $1'
      into leg using v_site;
    insert into public.s01_customer_recoveries (id, receipt_no, date, customer_id, customer_name, payment_method, amount,
        reference_no, received_by, created_at)
    select r->>'id', r->>'receipt_no', (r->>'date')::date, r->>'customer_id', coalesce(r->>'customer_name', ''),
           coalesce(r->>'payment_method', 'Cash'), (r->>'amount')::numeric, coalesce(r->>'reference_no', ''),
           coalesce(r->>'received_by', ''), coalesce((r->>'created_at')::timestamptz, now())
      from jsonb_array_elements(leg) r
     where exists (select 1 from public.s01_customers cu where cu.id = r->>'customer_id')
    on conflict do nothing;
    get diagnostics n = row_count;
    v_log := v_log || jsonb_build_object('recovered_recoveries', n);
  end if;

  -- ---- daybook (snapshot first, in its original order) --------------------
  insert into public.s01_daybook_entries (id, date, time, particulars, category, cash_in, cash_out, reference_no, handled_by, created_at)
  select r.e->>'id', coalesce(nullif(r.e->>'date','')::date, current_date), coalesce(r.e->>'time', ''),
         coalesce(r.e->>'particulars', ''), coalesce(r.e->>'category', 'Shift Fuel'),
         coalesce((r.e->>'cashIn')::numeric, 0), coalesce((r.e->>'cashOut')::numeric, 0),
         r.e->>'referenceNo', coalesce(r.e->>'handledBy', ''),
         (coalesce(nullif(r.e->>'date','')::date, current_date) + time '12:00')::timestamptz
    from jsonb_array_elements(coalesce(d->'daybook', '[]')) with ordinality as r(e, ord)
   order by r.ord
  on conflict do nothing;

  -- ...then vouchers that only exist in the old side table, in the order they were written
  v_rec := '[]'::jsonb;
  if to_regclass('public.legacy_daybook_vouchers') is not null then
    execute 'select coalesce(jsonb_agg(to_jsonb(l) order by l.created_at), ''[]''::jsonb) from public.legacy_daybook_vouchers l where l.site_id = $1'
      into leg using v_site;
    with ins as (
      insert into public.s01_daybook_entries (id, date, time, particulars, category, cash_in, cash_out, reference_no, handled_by, created_at)
      select r.e->>'id', (r.e->>'date')::date, coalesce(r.e->>'time', ''), coalesce(r.e->>'particulars', ''),
             coalesce(r.e->>'category', 'Shift Fuel'), coalesce((r.e->>'cash_in')::numeric, 0),
             coalesce((r.e->>'cash_out')::numeric, 0), r.e->>'reference_no', coalesce(r.e->>'handled_by', ''),
             coalesce((r.e->>'created_at')::timestamptz, now())
        from jsonb_array_elements(leg) with ordinality as r(e, ord)
       order by r.ord
      on conflict do nothing
      returning id, date, particulars, category, cash_out, reference_no, handled_by
    )
    select coalesce(jsonb_agg(to_jsonb(ins)), '[]'::jsonb) into v_rec from ins;
    v_log := v_log || jsonb_build_object('recovered_daybook_vouchers', jsonb_array_length(v_rec));
  end if;

  -- ---- expenses & staff (needed before rebuilding recovered vouchers) -----
  insert into public.s01_expenses (id, voucher_no, date, category, description, payee, amount, payment_mode, approved_by, created_at)
  select r->>'id', coalesce(r->>'voucherNo', r->>'id'), coalesce(nullif(r->>'date','')::date, current_date), coalesce(r->>'category', 'Misc'),
         coalesce(r->>'description', ''), coalesce(r->>'payee', ''), (r->>'amount')::numeric,
         case when r->>'paymentMode' = 'Bank' then 'Bank' else 'Cash' end, coalesce(r->>'approvedBy', ''),
         (coalesce(nullif(r->>'date','')::date, current_date) + time '12:00')::timestamptz
    from jsonb_array_elements(coalesce(d->'expenses', '[]')) r
   where (r->>'amount')::numeric > 0
  on conflict do nothing;

  insert into public.s01_staff_members (id, name, role, phone, monthly_salary, daily_advance_limit, joining_date, status, is_active)
  select r->>'id', r->>'name', coalesce(r->>'role', 'Pump Attendant'), coalesce(r->>'phone', ''),
         coalesce((r->>'monthlySalary')::numeric, 0), coalesce((r->>'dailyAdvanceLimit')::numeric, 0),
         nullif(r->>'joiningDate', '')::date,
         case when r->>'status' in ('On Duty', 'Off Duty', 'On Leave') then r->>'status' else 'On Duty' end, true
    from jsonb_array_elements(coalesce(d->'staff', '[]')) r
  on conflict do nothing;

  -- advances carried in the old "currentAdvances" figure become one outstanding advance per employee
  insert into public.s01_staff_advances (id, staff_id, date, amount, reason, status, recorded_by)
  select 'ADV-BF-' || (r->>'id'), r->>'id', current_date, (r->>'currentAdvances')::numeric,
         'Balance brought forward from previous software', 'Outstanding', 'Migration'
    from jsonb_array_elements(coalesce(d->'staff', '[]')) r
   where coalesce((r->>'currentAdvances')::numeric, 0) > 0
  on conflict do nothing;

  -- ---- rebuild the expense / advance behind recovered daybook vouchers ----
  -- (a recovered "Expense: <category> (<description>)" cash-out with a voucher number had its
  --  expense record lost together with the snapshot; recreate it so reports match the cash book)
  insert into public.s01_expenses (id, voucher_no, date, category, description, payee, amount, payment_mode, approved_by, created_at)
  select 'EXP-R-' || (v->>'reference_no'), v->>'reference_no', (v->>'date')::date,
         coalesce(substring(v->>'particulars' from '^Expense: (.*) \(.*\)$'), 'Misc'),
         coalesce(substring(v->>'particulars' from '\((.*)\)$'), v->>'particulars') || ' [recovered from cash-book voucher ' || (v->>'id') || ']',
         'Not recorded (recovered)', (v->>'cash_out')::numeric, 'Cash', coalesce(v->>'handled_by', ''), now()
    from jsonb_array_elements(v_rec) v
   where v->>'particulars' like 'Expense: %' and coalesce(v->>'reference_no', '') <> '' and (v->>'cash_out')::numeric > 0
     and not exists (select 1 from public.s01_expenses e where e.voucher_no = v->>'reference_no')
  on conflict do nothing;
  update public.s01_daybook_entries db set source_type = 'expense', source_id = 'EXP-R-' || db.reference_no
   where db.id in (select v->>'id' from jsonb_array_elements(v_rec) v where v->>'particulars' like 'Expense: %')
     and exists (select 1 from public.s01_expenses e where e.id = 'EXP-R-' || db.reference_no);

  insert into public.s01_staff_advances (id, staff_id, date, amount, reason, status, recorded_by, created_at)
  select 'ADV-R-' || (v->>'reference_no'), st.id, (v->>'date')::date, (v->>'cash_out')::numeric,
         coalesce(substring(v->>'particulars' from ' — (.*)$'), 'Recovered advance') || ' [recovered from cash-book voucher ' || (v->>'id') || ']',
         'Outstanding', coalesce(v->>'handled_by', ''), now()
    from jsonb_array_elements(v_rec) v
    join public.s01_staff_members st on lower(st.name) = lower(substring(v->>'particulars' from '^Staff Advance: (.*?) — '))
   where v->>'particulars' like 'Staff Advance: %' and coalesce(v->>'reference_no', '') <> '' and (v->>'cash_out')::numeric > 0
  on conflict do nothing;
  update public.s01_daybook_entries db set source_type = 'staff_advance', source_id = 'ADV-R-' || db.reference_no
   where db.id in (select v->>'id' from jsonb_array_elements(v_rec) v where v->>'particulars' like 'Staff Advance: %')
     and exists (select 1 from public.s01_staff_advances a where a.id = 'ADV-R-' || db.reference_no);

  -- ---- lubricants & suppliers ---------------------------------------------
  insert into public.s01_lubricant_products (id, name, brand, grade, pack_size, opening_stock, min_stock_alert, cost_price, sale_price)
  select r->>'id', r->>'name', coalesce(r->>'brand', ''), coalesce(r->>'grade', ''), coalesce(r->>'packSize', ''),
         greatest(coalesce((r->>'stockCans')::int, 0), 0), greatest(coalesce((r->>'minStockAlert')::int, 0), 0),
         coalesce((r->>'costPrice')::numeric, 0), coalesce((r->>'salePrice')::numeric, 0)
    from jsonb_array_elements(coalesce(d->'lubricants', '[]')) r
  on conflict do nothing;

  insert into public.s01_suppliers (id, name, company, category, phone, opening_balance)
  select r->>'id', r->>'name', coalesce(r->>'company', ''), coalesce(r->>'category', ''), coalesce(r->>'phone', ''),
         coalesce((r->>'balanceDue')::numeric, 0)
    from jsonb_array_elements(coalesce(d->'suppliers', '[]')) r
  on conflict do nothing;

  -- ---- tariff revisions ----------------------------------------------------
  insert into public.s01_tariff_revisions (id, date, effective_date, notification_no, old_rates, new_rates, tank_snapshots,
      net_inventory_gain_loss, revised_by, notes, created_at)
  select r->>'id', coalesce(nullif(r->>'date','')::date, current_date), coalesce(r->>'effectiveDate', ''),
         coalesce(r->>'notificationNo', ''), coalesce(r->'oldRates', '{}'), coalesce(r->'newRates', '{}'),
         coalesce(r->'tankSnapshots', '[]'), coalesce((r->>'netInventoryGainLoss')::numeric, 0), coalesce(r->>'revisedBy', ''), r->>'notes',
         (coalesce(nullif(r->>'date','')::date, current_date) + time '12:00')::timestamptz
    from jsonb_array_elements(coalesce(d->'tariffHistory', '[]')) r
  on conflict do nothing;

  if to_regclass('public.legacy_tariff_revisions') is not null then
    execute 'select coalesce(jsonb_agg(to_jsonb(l) order by l.created_at), ''[]''::jsonb) from public.legacy_tariff_revisions l where l.site_id = $1'
      into leg using v_site;
    insert into public.s01_tariff_revisions (id, date, effective_date, notification_no, net_inventory_gain_loss, revised_by, notes, created_at)
    select r->>'id', (r->>'date')::date, coalesce(r->>'effective_date', ''), coalesce(r->>'notification_no', ''),
           coalesce((r->>'net_inventory_gain_loss')::numeric, 0), coalesce(r->>'revised_by', ''), r->>'notes',
           coalesce((r->>'created_at')::timestamptz, now())
      from jsonb_array_elements(leg) r
    on conflict do nothing;
    get diagnostics n = row_count;
    v_log := v_log || jsonb_build_object('recovered_tariff_revisions', n);
  end if;

  -- ---- continue document numbering after the highest existing number -------
  insert into public.s01_doc_counters (kind, last_value)
  select 'slip', max(coalesce(substring(slip_no from '(\d+)$'), '0')::bigint) from public.s01_credit_slips
  having max(coalesce(substring(slip_no from '(\d+)$'), '0')::bigint) is not null
  on conflict (kind) do update set last_value = greatest(s01_doc_counters.last_value, excluded.last_value);
  insert into public.s01_doc_counters (kind, last_value)
  select 'receipt', max(coalesce(substring(receipt_no from '(\d+)$'), '0')::bigint) from public.s01_customer_recoveries
  having max(coalesce(substring(receipt_no from '(\d+)$'), '0')::bigint) is not null
  on conflict (kind) do update set last_value = greatest(s01_doc_counters.last_value, excluded.last_value);
  insert into public.s01_doc_counters (kind, last_value)
  select 'voucher', max(coalesce(substring(voucher_no from '(\d+)$'), '0')::bigint) from public.s01_expenses
  having max(coalesce(substring(voucher_no from '(\d+)$'), '0')::bigint) is not null
  on conflict (kind) do update set last_value = greatest(s01_doc_counters.last_value, excluded.last_value);

  insert into public.migration_log (name, details) values ('legacy-import:' || v_site, v_log);
  raise notice '[%] legacy import finished: %', v_site, v_log;
end $mig$;

-- =========================================================================
-- DATA MIGRATION for 'SITE-02' -> tables s02_*
-- -------------------------------------------------------------------------
-- Source 1: the old JSON snapshot   (legacy_stations.data)         — authoritative
-- Source 2: the old side tables     (legacy_fuel_sales, ...)       — any record that is
--           NOT in the snapshot is recovered too (a stale browser could overwrite
--           the snapshot and silently drop records that had already reached these tables).
-- Nothing is deleted from the archive. Re-running is safe (guarded by migration_log,
-- and every insert is ON CONFLICT DO NOTHING).
--
-- Balances are converted to "opening balance + transactions" so that every
-- balance shown before the migration is identical after it:
--   customer opening  = old balance - snapshot slips + snapshot recoveries
--   bank opening      = old balance - signed snapshot bank transactions
--   supplier opening  = old balance due
--   lube opening      = old stock
--   OMC invoice       = old paid amount - snapshot payments
--   tank / nozzle     = old level / old meter reading
-- =========================================================================
do $mig$
declare
  v_site   constant text := 'SITE-02';
  d        jsonb;
  leg      jsonb;
  v_rec    jsonb;
  v_log    jsonb := '{}'::jsonb;
  n        int;
begin
  if exists (select 1 from public.migration_log where name = 'legacy-import:' || v_site) then
    raise notice '[%] legacy import already done - skipping', v_site;
    return;
  end if;

  if to_regclass('public.legacy_stations') is not null then
    execute 'select ls.data from public.legacy_stations ls where ls.site_id = $1' into d using v_site;
  end if;
  if d is null then
    insert into public.migration_log (name, details) values ('legacy-import:' || v_site, '{"note":"no legacy snapshot found"}');
    return;
  end if;

  -- ---- station profile & settings ---------------------------------------
  update public.stations s set
    code         = coalesce(d->'siteInfo'->>'code', s.code),
    name         = coalesce(d->'siteInfo'->>'name', s.name),
    location     = coalesce(d->'siteInfo'->>'location', s.location),
    brand        = coalesce(d->'siteInfo'->>'brand', s.brand),
    brand_color  = coalesce(d->'siteInfo'->>'brandColor', s.brand_color),
    phone        = coalesce(d->'siteInfo'->>'phone', s.phone),
    manager_name = coalesce(d->'siteInfo'->>'managerName', s.manager_name),
    ntn          = coalesce(d->'siteInfo'->>'ntn', s.ntn)
  where s.site_id = v_site;

  update public.s02_station_settings set
    rate_pmg            = coalesce((d->'settings'->'rates'->>'PMG Super')::numeric, rate_pmg),
    rate_hsd            = coalesce((d->'settings'->'rates'->>'HSD Diesel')::numeric, rate_hsd),
    rate_octane         = coalesce((d->'settings'->'rates'->>'Hi-Octane')::numeric, rate_octane),
    station_phone       = coalesce(d->'settings'->>'stationPhone', station_phone),
    manager_contact     = coalesce(d->'settings'->>'managerContact', manager_contact),
    receipt_header      = coalesce(d->'settings'->>'receiptHeader', receipt_header),
    receipt_footer      = coalesce(d->'settings'->>'receiptFooter', receipt_footer),
    low_stock_alert_pct = coalesce((d->'settings'->>'lowStockAlertPct')::numeric, low_stock_alert_pct),
    cash_difference_alert_limit = coalesce((d->'settings'->>'cashDifferenceAlertLimit')::numeric, cash_difference_alert_limit)
  where id = 'main';

  -- ---- tanks & nozzles ---------------------------------------------------
  insert into public.s02_tanks (id, tank_no, fuel_type, capacity_liters, min_reserve_liters, initial_liters, initial_dip_mm)
  select t->>'id', (t->>'tankNo')::int, t->>'fuelType', (t->>'capacityLiters')::numeric,
         coalesce((t->>'minReserveLiters')::numeric, 0),
         coalesce((t->>'currentLiters')::numeric, 0), coalesce((t->>'currentDipMm')::numeric, 0)
    from jsonb_array_elements(coalesce(d->'tanks', '[]')) t
  on conflict do nothing;

  insert into public.s02_nozzles (id, tank_id, dispenser_no, nozzle_no, initial_meter, testing_liters, assigned_staff, is_active)
  select z->>'id', z->>'tankId', (z->>'dispenserNo')::int, (z->>'nozzleNo')::int,
         greatest(coalesce((z->>'closingMeter')::numeric, 0), coalesce((z->>'openingMeter')::numeric, 0)),
         coalesce((z->>'testingLiters')::numeric, 0), coalesce(z->>'assignedStaff', ''), true
    from jsonb_array_elements(coalesce(d->'nozzles', '[]')) z
  on conflict do nothing;

  -- ---- shifts & fuel sales ------------------------------------------------
  insert into public.s02_shifts (id, shift_name, date, incharge, status, start_time, end_time, total_fuel_sales,
      total_lube_sales, credit_sales, digital_payments, shift_expenses, credit_recoveries, expected_cash,
      actual_cash, shortage_excess, notes, created_at)
  select r->>'id', coalesce(r->>'shiftName', 'Morning'), coalesce(nullif(r->>'date','')::date, current_date),
         coalesce(r->>'incharge', ''), coalesce(r->>'status', 'Closed'), coalesce(r->>'startTime', ''), coalesce(r->>'endTime', ''),
         coalesce((r->>'totalFuelSales')::numeric, 0), coalesce((r->>'totalLubeSales')::numeric, 0),
         coalesce((r->>'creditSales')::numeric, 0), coalesce((r->>'digitalPayments')::numeric, 0),
         coalesce((r->>'shiftExpenses')::numeric, 0), coalesce((r->>'creditRecoveries')::numeric, 0),
         coalesce((r->>'expectedCash')::numeric, 0), coalesce((r->>'actualCash')::numeric, 0),
         coalesce((r->>'shortageExcess')::numeric, 0), r->>'notes',
         (coalesce(nullif(r->>'date','')::date, current_date) + time '12:00')::timestamptz
    from jsonb_array_elements(coalesce(d->'shifts', '[]')) r
  on conflict do nothing;

  insert into public.s02_fuel_sales (id, date, shift_name, shift_id, nozzle_id, dispenser_no, nozzle_no, fuel_type,
      opening_meter, closing_meter, testing_liters, net_liters, rate_per_liter, total_amount, cashier_name, created_at)
  select r->>'id', coalesce(nullif(r->>'date','')::date, current_date),
         coalesce((select sh->>'shiftName' from jsonb_array_elements(coalesce(d->'shifts','[]')) sh where sh->>'id' = r->>'shiftId' limit 1), 'Morning'),
         r->>'shiftId', r->>'nozzleId', coalesce((r->>'dispenserNo')::int, 0), coalesce((r->>'nozzleNo')::int, 0),
         r->>'fuelType', (r->>'openingMeter')::numeric, greatest((r->>'closingMeter')::numeric, (r->>'openingMeter')::numeric),
         coalesce((r->>'testingLiters')::numeric, 0), greatest(coalesce((r->>'netLiters')::numeric, 0), 0),
         (r->>'ratePerLiter')::numeric, (r->>'totalAmount')::numeric, coalesce(r->>'cashierName', ''),
         (coalesce(nullif(r->>'date','')::date, current_date) + time '12:00')::timestamptz
    from jsonb_array_elements(coalesce(d->'fuelSales', '[]')) r
  on conflict do nothing;

  -- side-table sales that are not in the snapshot
  if to_regclass('public.legacy_fuel_sales') is not null then
    execute 'select coalesce(jsonb_agg(to_jsonb(l) order by l.created_at), ''[]''::jsonb) from public.legacy_fuel_sales l where l.site_id = $1'
      into leg using v_site;
    insert into public.s02_fuel_sales (id, date, shift_name, nozzle_id, dispenser_no, nozzle_no, fuel_type,
        opening_meter, closing_meter, testing_liters, net_liters, rate_per_liter, total_amount, cashier_name, created_at)
    select r->>'id', (r->>'date')::date, coalesce(r->>'shift', 'Morning'), r->>'nozzle_id',
           coalesce((select nz.dispenser_no from public.s02_nozzles nz where nz.id = r->>'nozzle_id'), 0),
           coalesce((select nz.nozzle_no from public.s02_nozzles nz where nz.id = r->>'nozzle_id'), 0),
           r->>'fuel_type', (r->>'start_meter')::numeric, greatest((r->>'end_meter')::numeric, (r->>'start_meter')::numeric),
           0, (r->>'liters_sold')::numeric, (r->>'rate')::numeric, (r->>'amount')::numeric,
           coalesce(r->>'recorded_by', ''), coalesce((r->>'created_at')::timestamptz, now())
      from jsonb_array_elements(leg) r
    on conflict do nothing;
    get diagnostics n = row_count;
    v_log := v_log || jsonb_build_object('recovered_fuel_sales', n);
  end if;

  -- ---- tank dips ---------------------------------------------------------
  insert into public.s02_tank_dips (id, date, tank_id, tank_no, fuel_type, morning_dip_mm, morning_liters, decanted_liters,
      dispensed_liters, book_stock_liters, closing_dip_mm, closing_physical_liters, variance_liters, water_dip_mm, inspector, created_at)
  select r->>'id', coalesce(nullif(r->>'date','')::date, current_date), r->>'tankId', (r->>'tankNo')::int, r->>'fuelType',
         coalesce((r->>'morningDipMm')::numeric, 0), coalesce((r->>'morningLiters')::numeric, 0),
         coalesce((r->>'decantedLiters')::numeric, 0), coalesce((r->>'dispensedLiters')::numeric, 0),
         coalesce((r->>'bookStockLiters')::numeric, 0), coalesce((r->>'closingDipMm')::numeric, 0),
         coalesce((r->>'closingPhysicalLiters')::numeric, 0), coalesce((r->>'varianceLiters')::numeric, 0),
         coalesce((r->>'waterDipMm')::numeric, 0), coalesce(r->>'inspector', ''),
         (coalesce(nullif(r->>'date','')::date, current_date) + time '12:00')::timestamptz
    from jsonb_array_elements(coalesce(d->'tankDips', '[]')) r
   where exists (select 1 from public.s02_tanks tk where tk.id = r->>'tankId')
  on conflict do nothing;

  if to_regclass('public.legacy_tank_dips') is not null then
    execute 'select coalesce(jsonb_agg(to_jsonb(l) order by l.created_at), ''[]''::jsonb) from public.legacy_tank_dips l where l.site_id = $1'
      into leg using v_site;
    insert into public.s02_tank_dips (id, date, tank_id, tank_no, fuel_type, morning_dip_mm, morning_liters, decanted_liters,
        dispensed_liters, book_stock_liters, closing_dip_mm, closing_physical_liters, variance_liters, water_dip_mm, inspector, created_at)
    select r->>'id', (r->>'date')::date, r->>'tank_id', (r->>'tank_no')::int, r->>'fuel_type',
           coalesce((r->>'opening_dip_mm')::numeric, 0), coalesce((r->>'opening_liters')::numeric, 0), 0,
           coalesce((r->>'sales_during_shift')::numeric, 0), coalesce((r->>'expected_liters')::numeric, 0),
           coalesce((r->>'closing_dip_mm')::numeric, 0), (r->>'closing_physical_liters')::numeric,
           coalesce((r->>'variance_liters')::numeric, 0), 0, coalesce(r->>'recorded_by', ''),
           coalesce((r->>'created_at')::timestamptz, now())
      from jsonb_array_elements(leg) r
     where exists (select 1 from public.s02_tanks tk where tk.id = r->>'tank_id')
    on conflict do nothing;
    get diagnostics n = row_count;
    v_log := v_log || jsonb_build_object('recovered_tank_dips', n);
  end if;

  -- ---- OMC invoices & payments -------------------------------------------
  insert into public.s02_omc_invoices (id, invoice_no, date, brand, tank_lorry_no, driver_name, fuel_type,
      invoice_volume_liters, decanted_volume_liters, rate_per_liter, freight_amount, total_amount, opening_paid_amount, created_at)
  select r->>'id', r->>'invoiceNo', coalesce(nullif(r->>'date','')::date, current_date), coalesce(r->>'brand', ''),
         coalesce(r->>'tankLorryNo', ''), coalesce(r->>'driverName', ''), r->>'fuelType',
         coalesce((r->>'invoiceVolumeLiters')::numeric, 0), coalesce((r->>'decantedVolumeLiters')::numeric, 0),
         coalesce((r->>'ratePerLiter')::numeric, 0), coalesce((r->>'freightAmount')::numeric, 0),
         coalesce((r->>'totalAmount')::numeric, 0),
         coalesce((r->>'paidAmount')::numeric, 0)
           - coalesce((select sum((p->>'amount')::numeric) from jsonb_array_elements(coalesce(d->'omcPayments','[]')) p
                        where p->>'invoiceNo' = r->>'invoiceNo'), 0),
         (coalesce(nullif(r->>'date','')::date, current_date) + time '12:00')::timestamptz
    from jsonb_array_elements(coalesce(d->'omcInvoices', '[]')) r
  on conflict do nothing;

  insert into public.s02_omc_payments (id, date, invoice_no, payment_method, bank_name, reference_no, amount, recorded_by, created_at)
  select r->>'id', coalesce(nullif(r->>'date','')::date, current_date), r->>'invoiceNo',
         coalesce(r->>'paymentMethod', 'Bank Transfer'), coalesce(r->>'bankName', ''), coalesce(r->>'referenceNo', ''),
         (r->>'amount')::numeric, coalesce(r->>'recordedBy', ''),
         (coalesce(nullif(r->>'date','')::date, current_date) + time '12:00')::timestamptz
    from jsonb_array_elements(coalesce(d->'omcPayments', '[]')) r
   where (r->>'amount')::numeric > 0
  on conflict do nothing;

  if to_regclass('public.legacy_omc_invoices') is not null then
    execute 'select coalesce(jsonb_agg(to_jsonb(l) order by l.created_at), ''[]''::jsonb) from public.legacy_omc_invoices l where l.site_id = $1'
      into leg using v_site;
    insert into public.s02_omc_invoices (id, invoice_no, date, brand, fuel_type, invoice_volume_liters, decanted_volume_liters,
        rate_per_liter, total_amount, opening_paid_amount, created_at)
    select r->>'id', r->>'invoice_no', (r->>'date')::date, coalesce(r->>'omc_name', ''), r->>'fuel_type',
           coalesce((r->>'liters')::numeric, 0), coalesce((r->>'liters')::numeric, 0), coalesce((r->>'product_rate')::numeric, 0),
           (r->>'total_amount')::numeric, coalesce((r->>'paid_amount')::numeric, 0),
           coalesce((r->>'created_at')::timestamptz, now())
      from jsonb_array_elements(leg) r
     where not exists (select 1 from public.s02_omc_invoices i where i.invoice_no = r->>'invoice_no')
    on conflict do nothing;
    get diagnostics n = row_count;
    v_log := v_log || jsonb_build_object('recovered_omc_invoices', n);
  end if;

  -- ---- banking -------------------------------------------------------------
  insert into public.s02_bank_accounts (id, bank_name, account_title, account_number, branch, opening_balance)
  select b->>'id', b->>'bankName', coalesce(b->>'accountTitle', ''), coalesce(b->>'accountNumber', ''), coalesce(b->>'branch', ''),
         coalesce((b->>'currentBalance')::numeric, 0)
           - coalesce((select sum(case when x->>'type' in ('Deposit') then (x->>'amount')::numeric else -(x->>'amount')::numeric end)
                         from jsonb_array_elements(coalesce(d->'bankTransactions','[]')) x where x->>'bankId' = b->>'id'), 0)
    from jsonb_array_elements(coalesce(d->'bankAccounts', '[]')) b
  on conflict do nothing;

  insert into public.s02_bank_transactions (id, bank_id, date, type, amount, deposit_slip_no, description, created_at)
  select x->>'id', x->>'bankId', coalesce(nullif(x->>'date','')::date, current_date), x->>'type', (x->>'amount')::numeric,
         x->>'depositSlipNo', coalesce(x->>'description', ''),
         (coalesce(nullif(x->>'date','')::date, current_date) + time '12:00')::timestamptz
    from jsonb_array_elements(coalesce(d->'bankTransactions', '[]')) x
   where (x->>'amount')::numeric > 0
     and exists (select 1 from public.s02_bank_accounts ba where ba.id = x->>'bankId')
  on conflict do nothing;

  insert into public.s02_owner_transfers (id, date, amount, bank_id, bank_name, account_title, account_number, reference_no,
      status, notes, transferred_by, created_at)
  select r->>'id', coalesce(nullif(r->>'date','')::date, current_date), (r->>'amount')::numeric, coalesce(r->>'bankId', ''),
         coalesce(r->>'bankName', ''), coalesce(r->>'accountTitle', ''), coalesce(r->>'accountNumber', ''),
         coalesce(r->>'referenceNo', ''), coalesce(r->>'status', 'Completed'), r->>'notes', coalesce(r->>'transferredBy', ''),
         (coalesce(nullif(r->>'date','')::date, current_date) + time '12:00')::timestamptz
    from jsonb_array_elements(coalesce(d->'ownerTransfers', '[]')) r
   where (r->>'amount')::numeric > 0
  on conflict do nothing;

  -- ---- customers, slips, recoveries --------------------------------------
  insert into public.s02_customers (id, name, business_name, phone, vehicle_numbers, credit_limit, opening_balance, status)
  select c->>'id', coalesce(c->>'name', c->>'businessName'), coalesce(c->>'businessName', c->>'name'), coalesce(c->>'phone', ''),
         coalesce(array(select jsonb_array_elements_text(coalesce(c->'vehicleNumbers', '[]'))), '{}'),
         coalesce((c->>'creditLimit')::numeric, 0),
         coalesce((c->>'currentBalance')::numeric, 0)
           - coalesce((select sum((s->>'totalAmount')::numeric) from jsonb_array_elements(coalesce(d->'creditSlips','[]')) s where s->>'customerId' = c->>'id'), 0)
           + coalesce((select sum((r->>'amount')::numeric) from jsonb_array_elements(coalesce(d->'recoveries','[]')) r where r->>'customerId' = c->>'id'), 0),
         case when c->>'status' = 'Hold' then 'Hold' else 'Active' end
    from jsonb_array_elements(coalesce(d->'customers', '[]')) c
  on conflict do nothing;

  insert into public.s02_credit_slips (id, slip_no, date, customer_id, customer_name, vehicle_no, driver_name, fuel_type,
      liters, rate, total_amount, authorized_by, created_at)
  select s->>'id', s->>'slipNo', coalesce(nullif(s->>'date','')::date, current_date), s->>'customerId', coalesce(s->>'customerName', ''),
         coalesce(s->>'vehicleNo', ''), coalesce(s->>'driverName', ''), s->>'fuelType',
         greatest((s->>'liters')::numeric, 0.001), coalesce((s->>'rate')::numeric, 0), coalesce((s->>'totalAmount')::numeric, 0),
         coalesce(s->>'authorizedBy', ''), (coalesce(nullif(s->>'date','')::date, current_date) + time '12:00')::timestamptz
    from jsonb_array_elements(coalesce(d->'creditSlips', '[]')) s
   where exists (select 1 from public.s02_customers cu where cu.id = s->>'customerId')
  on conflict do nothing;

  insert into public.s02_customer_recoveries (id, receipt_no, date, customer_id, customer_name, payment_method, amount,
      reference_no, received_by, created_at)
  select r->>'id', r->>'receiptNo', coalesce(nullif(r->>'date','')::date, current_date), r->>'customerId', coalesce(r->>'customerName', ''),
         coalesce(r->>'paymentMethod', 'Cash'), (r->>'amount')::numeric, coalesce(r->>'referenceNo', ''), coalesce(r->>'receivedBy', ''),
         (coalesce(nullif(r->>'date','')::date, current_date) + time '12:00')::timestamptz
    from jsonb_array_elements(coalesce(d->'recoveries', '[]')) r
   where (r->>'amount')::numeric > 0
     and exists (select 1 from public.s02_customers cu where cu.id = r->>'customerId')
  on conflict do nothing;

  -- side-table credit slips / recoveries that are not in the snapshot.
  -- (Their amounts are ADDED on top of the snapshot-based opening balance, i.e. they raise/lower the customer's due.)
  if to_regclass('public.legacy_credit_fuel_slips') is not null then
    execute 'select coalesce(jsonb_agg(to_jsonb(l) order by l.created_at), ''[]''::jsonb) from public.legacy_credit_fuel_slips l where l.site_id = $1'
      into leg using v_site;
    insert into public.s02_credit_slips (id, slip_no, date, customer_id, customer_name, vehicle_no, driver_name, fuel_type,
        liters, rate, total_amount, authorized_by, created_at)
    select r->>'id', r->>'slip_no', (r->>'date')::date, r->>'customer_id', coalesce(r->>'customer_name', ''),
           coalesce(r->>'vehicle_no', ''), coalesce(r->>'driver_name', ''), r->>'fuel_type', (r->>'liters')::numeric,
           (r->>'rate')::numeric, (r->>'total_amount')::numeric, coalesce(r->>'authorized_by', ''),
           coalesce((r->>'created_at')::timestamptz, now())
      from jsonb_array_elements(leg) r
     where exists (select 1 from public.s02_customers cu where cu.id = r->>'customer_id')
    on conflict do nothing;
    get diagnostics n = row_count;
    v_log := v_log || jsonb_build_object('recovered_credit_slips', n);
  end if;

  if to_regclass('public.legacy_customer_recoveries') is not null then
    execute 'select coalesce(jsonb_agg(to_jsonb(l) order by l.created_at), ''[]''::jsonb) from public.legacy_customer_recoveries l where l.site_id = $1'
      into leg using v_site;
    insert into public.s02_customer_recoveries (id, receipt_no, date, customer_id, customer_name, payment_method, amount,
        reference_no, received_by, created_at)
    select r->>'id', r->>'receipt_no', (r->>'date')::date, r->>'customer_id', coalesce(r->>'customer_name', ''),
           coalesce(r->>'payment_method', 'Cash'), (r->>'amount')::numeric, coalesce(r->>'reference_no', ''),
           coalesce(r->>'received_by', ''), coalesce((r->>'created_at')::timestamptz, now())
      from jsonb_array_elements(leg) r
     where exists (select 1 from public.s02_customers cu where cu.id = r->>'customer_id')
    on conflict do nothing;
    get diagnostics n = row_count;
    v_log := v_log || jsonb_build_object('recovered_recoveries', n);
  end if;

  -- ---- daybook (snapshot first, in its original order) --------------------
  insert into public.s02_daybook_entries (id, date, time, particulars, category, cash_in, cash_out, reference_no, handled_by, created_at)
  select r.e->>'id', coalesce(nullif(r.e->>'date','')::date, current_date), coalesce(r.e->>'time', ''),
         coalesce(r.e->>'particulars', ''), coalesce(r.e->>'category', 'Shift Fuel'),
         coalesce((r.e->>'cashIn')::numeric, 0), coalesce((r.e->>'cashOut')::numeric, 0),
         r.e->>'referenceNo', coalesce(r.e->>'handledBy', ''),
         (coalesce(nullif(r.e->>'date','')::date, current_date) + time '12:00')::timestamptz
    from jsonb_array_elements(coalesce(d->'daybook', '[]')) with ordinality as r(e, ord)
   order by r.ord
  on conflict do nothing;

  -- ...then vouchers that only exist in the old side table, in the order they were written
  v_rec := '[]'::jsonb;
  if to_regclass('public.legacy_daybook_vouchers') is not null then
    execute 'select coalesce(jsonb_agg(to_jsonb(l) order by l.created_at), ''[]''::jsonb) from public.legacy_daybook_vouchers l where l.site_id = $1'
      into leg using v_site;
    with ins as (
      insert into public.s02_daybook_entries (id, date, time, particulars, category, cash_in, cash_out, reference_no, handled_by, created_at)
      select r.e->>'id', (r.e->>'date')::date, coalesce(r.e->>'time', ''), coalesce(r.e->>'particulars', ''),
             coalesce(r.e->>'category', 'Shift Fuel'), coalesce((r.e->>'cash_in')::numeric, 0),
             coalesce((r.e->>'cash_out')::numeric, 0), r.e->>'reference_no', coalesce(r.e->>'handled_by', ''),
             coalesce((r.e->>'created_at')::timestamptz, now())
        from jsonb_array_elements(leg) with ordinality as r(e, ord)
       order by r.ord
      on conflict do nothing
      returning id, date, particulars, category, cash_out, reference_no, handled_by
    )
    select coalesce(jsonb_agg(to_jsonb(ins)), '[]'::jsonb) into v_rec from ins;
    v_log := v_log || jsonb_build_object('recovered_daybook_vouchers', jsonb_array_length(v_rec));
  end if;

  -- ---- expenses & staff (needed before rebuilding recovered vouchers) -----
  insert into public.s02_expenses (id, voucher_no, date, category, description, payee, amount, payment_mode, approved_by, created_at)
  select r->>'id', coalesce(r->>'voucherNo', r->>'id'), coalesce(nullif(r->>'date','')::date, current_date), coalesce(r->>'category', 'Misc'),
         coalesce(r->>'description', ''), coalesce(r->>'payee', ''), (r->>'amount')::numeric,
         case when r->>'paymentMode' = 'Bank' then 'Bank' else 'Cash' end, coalesce(r->>'approvedBy', ''),
         (coalesce(nullif(r->>'date','')::date, current_date) + time '12:00')::timestamptz
    from jsonb_array_elements(coalesce(d->'expenses', '[]')) r
   where (r->>'amount')::numeric > 0
  on conflict do nothing;

  insert into public.s02_staff_members (id, name, role, phone, monthly_salary, daily_advance_limit, joining_date, status, is_active)
  select r->>'id', r->>'name', coalesce(r->>'role', 'Pump Attendant'), coalesce(r->>'phone', ''),
         coalesce((r->>'monthlySalary')::numeric, 0), coalesce((r->>'dailyAdvanceLimit')::numeric, 0),
         nullif(r->>'joiningDate', '')::date,
         case when r->>'status' in ('On Duty', 'Off Duty', 'On Leave') then r->>'status' else 'On Duty' end, true
    from jsonb_array_elements(coalesce(d->'staff', '[]')) r
  on conflict do nothing;

  -- advances carried in the old "currentAdvances" figure become one outstanding advance per employee
  insert into public.s02_staff_advances (id, staff_id, date, amount, reason, status, recorded_by)
  select 'ADV-BF-' || (r->>'id'), r->>'id', current_date, (r->>'currentAdvances')::numeric,
         'Balance brought forward from previous software', 'Outstanding', 'Migration'
    from jsonb_array_elements(coalesce(d->'staff', '[]')) r
   where coalesce((r->>'currentAdvances')::numeric, 0) > 0
  on conflict do nothing;

  -- ---- rebuild the expense / advance behind recovered daybook vouchers ----
  -- (a recovered "Expense: <category> (<description>)" cash-out with a voucher number had its
  --  expense record lost together with the snapshot; recreate it so reports match the cash book)
  insert into public.s02_expenses (id, voucher_no, date, category, description, payee, amount, payment_mode, approved_by, created_at)
  select 'EXP-R-' || (v->>'reference_no'), v->>'reference_no', (v->>'date')::date,
         coalesce(substring(v->>'particulars' from '^Expense: (.*) \(.*\)$'), 'Misc'),
         coalesce(substring(v->>'particulars' from '\((.*)\)$'), v->>'particulars') || ' [recovered from cash-book voucher ' || (v->>'id') || ']',
         'Not recorded (recovered)', (v->>'cash_out')::numeric, 'Cash', coalesce(v->>'handled_by', ''), now()
    from jsonb_array_elements(v_rec) v
   where v->>'particulars' like 'Expense: %' and coalesce(v->>'reference_no', '') <> '' and (v->>'cash_out')::numeric > 0
     and not exists (select 1 from public.s02_expenses e where e.voucher_no = v->>'reference_no')
  on conflict do nothing;
  update public.s02_daybook_entries db set source_type = 'expense', source_id = 'EXP-R-' || db.reference_no
   where db.id in (select v->>'id' from jsonb_array_elements(v_rec) v where v->>'particulars' like 'Expense: %')
     and exists (select 1 from public.s02_expenses e where e.id = 'EXP-R-' || db.reference_no);

  insert into public.s02_staff_advances (id, staff_id, date, amount, reason, status, recorded_by, created_at)
  select 'ADV-R-' || (v->>'reference_no'), st.id, (v->>'date')::date, (v->>'cash_out')::numeric,
         coalesce(substring(v->>'particulars' from ' — (.*)$'), 'Recovered advance') || ' [recovered from cash-book voucher ' || (v->>'id') || ']',
         'Outstanding', coalesce(v->>'handled_by', ''), now()
    from jsonb_array_elements(v_rec) v
    join public.s02_staff_members st on lower(st.name) = lower(substring(v->>'particulars' from '^Staff Advance: (.*?) — '))
   where v->>'particulars' like 'Staff Advance: %' and coalesce(v->>'reference_no', '') <> '' and (v->>'cash_out')::numeric > 0
  on conflict do nothing;
  update public.s02_daybook_entries db set source_type = 'staff_advance', source_id = 'ADV-R-' || db.reference_no
   where db.id in (select v->>'id' from jsonb_array_elements(v_rec) v where v->>'particulars' like 'Staff Advance: %')
     and exists (select 1 from public.s02_staff_advances a where a.id = 'ADV-R-' || db.reference_no);

  -- ---- lubricants & suppliers ---------------------------------------------
  insert into public.s02_lubricant_products (id, name, brand, grade, pack_size, opening_stock, min_stock_alert, cost_price, sale_price)
  select r->>'id', r->>'name', coalesce(r->>'brand', ''), coalesce(r->>'grade', ''), coalesce(r->>'packSize', ''),
         greatest(coalesce((r->>'stockCans')::int, 0), 0), greatest(coalesce((r->>'minStockAlert')::int, 0), 0),
         coalesce((r->>'costPrice')::numeric, 0), coalesce((r->>'salePrice')::numeric, 0)
    from jsonb_array_elements(coalesce(d->'lubricants', '[]')) r
  on conflict do nothing;

  insert into public.s02_suppliers (id, name, company, category, phone, opening_balance)
  select r->>'id', r->>'name', coalesce(r->>'company', ''), coalesce(r->>'category', ''), coalesce(r->>'phone', ''),
         coalesce((r->>'balanceDue')::numeric, 0)
    from jsonb_array_elements(coalesce(d->'suppliers', '[]')) r
  on conflict do nothing;

  -- ---- tariff revisions ----------------------------------------------------
  insert into public.s02_tariff_revisions (id, date, effective_date, notification_no, old_rates, new_rates, tank_snapshots,
      net_inventory_gain_loss, revised_by, notes, created_at)
  select r->>'id', coalesce(nullif(r->>'date','')::date, current_date), coalesce(r->>'effectiveDate', ''),
         coalesce(r->>'notificationNo', ''), coalesce(r->'oldRates', '{}'), coalesce(r->'newRates', '{}'),
         coalesce(r->'tankSnapshots', '[]'), coalesce((r->>'netInventoryGainLoss')::numeric, 0), coalesce(r->>'revisedBy', ''), r->>'notes',
         (coalesce(nullif(r->>'date','')::date, current_date) + time '12:00')::timestamptz
    from jsonb_array_elements(coalesce(d->'tariffHistory', '[]')) r
  on conflict do nothing;

  if to_regclass('public.legacy_tariff_revisions') is not null then
    execute 'select coalesce(jsonb_agg(to_jsonb(l) order by l.created_at), ''[]''::jsonb) from public.legacy_tariff_revisions l where l.site_id = $1'
      into leg using v_site;
    insert into public.s02_tariff_revisions (id, date, effective_date, notification_no, net_inventory_gain_loss, revised_by, notes, created_at)
    select r->>'id', (r->>'date')::date, coalesce(r->>'effective_date', ''), coalesce(r->>'notification_no', ''),
           coalesce((r->>'net_inventory_gain_loss')::numeric, 0), coalesce(r->>'revised_by', ''), r->>'notes',
           coalesce((r->>'created_at')::timestamptz, now())
      from jsonb_array_elements(leg) r
    on conflict do nothing;
    get diagnostics n = row_count;
    v_log := v_log || jsonb_build_object('recovered_tariff_revisions', n);
  end if;

  -- ---- continue document numbering after the highest existing number -------
  insert into public.s02_doc_counters (kind, last_value)
  select 'slip', max(coalesce(substring(slip_no from '(\d+)$'), '0')::bigint) from public.s02_credit_slips
  having max(coalesce(substring(slip_no from '(\d+)$'), '0')::bigint) is not null
  on conflict (kind) do update set last_value = greatest(s02_doc_counters.last_value, excluded.last_value);
  insert into public.s02_doc_counters (kind, last_value)
  select 'receipt', max(coalesce(substring(receipt_no from '(\d+)$'), '0')::bigint) from public.s02_customer_recoveries
  having max(coalesce(substring(receipt_no from '(\d+)$'), '0')::bigint) is not null
  on conflict (kind) do update set last_value = greatest(s02_doc_counters.last_value, excluded.last_value);
  insert into public.s02_doc_counters (kind, last_value)
  select 'voucher', max(coalesce(substring(voucher_no from '(\d+)$'), '0')::bigint) from public.s02_expenses
  having max(coalesce(substring(voucher_no from '(\d+)$'), '0')::bigint) is not null
  on conflict (kind) do update set last_value = greatest(s02_doc_counters.last_value, excluded.last_value);

  insert into public.migration_log (name, details) values ('legacy-import:' || v_site, v_log);
  raise notice '[%] legacy import finished: %', v_site, v_log;
end $mig$;

-- =========================================================================
-- LOGIN ACCOUNTS
-- -------------------------------------------------------------------------
-- The previous software kept these usernames/passwords inside the public
-- JavaScript file. They are recreated here as real Supabase Auth accounts with
-- the SAME usernames and passwords, so everyone can still sign in today.
-- Every seeded account is flagged "must change password": the app forces a new
-- password at first sign-in. After that these defaults no longer work.
-- Add / disable / re-assign users later from Settings > Users (owner only).
-- =========================================================================
do $seed$
declare
  u     record;
  v_uid uuid;
begin
  for u in
    select * from (values
      ('owner',           'mashaal@owner', 'Station Owner',             'owner',   '0300-0000000', array['SITE-01', 'SITE-02']),
      ('owner.parco',     'parco@owner',   'Total PARCO Station Owner', 'owner',   '0300-1111111', array['SITE-01']),
      ('owner.pso',       'pso@owner',     'PSO Station Owner',         'owner',   '0321-2222222', array['SITE-02']),
      ('naveed.akhtar',   'manager123',    'Naveed Akhtar',             'manager', '0300-6729104', array['SITE-01']),
      ('tariq.cashier',   'cashier123',    'Tariq Mehmood',             'cashier', '0301-5582910', array['SITE-01']),
      ('tariq.manager',   'manager123',    'Chaudhry Tariq Mehmood',    'manager', '0321-4455667', array['SITE-02']),
      ('kamran.cashier',  'cashier123',    'Kamran Ali',                'cashier', '0300-9876543', array['SITE-02']),
      ('station.manager', 'manager123',    'Station Manager',           'manager', '0300-0000001', array['SITE-01', 'SITE-02']),
      ('station.cashier', 'cashier123',    'Station Cashier',           'cashier', '0300-0000002', array['SITE-01', 'SITE-02'])
    ) as t(username, password, full_name, role, phone, sites)
  loop
    select p.user_id into v_uid from public.profiles p where p.username = u.username;
    if v_uid is null then
      select au.id into v_uid from auth.users au where au.email = u.username || '@mashaal.internal';
      if v_uid is null then
        v_uid := public._create_auth_user(u.username, u.password);
      end if;
      insert into public.profiles (user_id, username, full_name, role, phone, is_active, must_change_password)
      values (v_uid, u.username, u.full_name, u.role, u.phone, true, true);
    end if;
    insert into public.profile_stations (user_id, site_id)
    select v_uid, s from unnest(u.sites) as s
    on conflict do nothing;
  end loop;
end $seed$;

-- =========================================================================
-- RESULT: what is now in the database (compare with your old data)
-- =========================================================================
select * from (
select 'SITE-01'::text as station, 'customers'::text as item, count(*)::numeric as value from public.s01_customers
union all select 'SITE-01', 'customer receivable (Rs)',
  (select coalesce(sum(opening_balance), 0) from public.s01_customers)
  + (select coalesce(sum(total_amount), 0) from public.s01_credit_slips)
  - (select coalesce(sum(amount), 0) from public.s01_customer_recoveries)
union all select 'SITE-01', 'safe cash (Rs)', (select coalesce(sum(cash_in - cash_out), 0) from public.s01_daybook_entries)
union all select 'SITE-01', 'daybook entries', count(*) from public.s01_daybook_entries
union all select 'SITE-01', 'fuel sales', count(*) from public.s01_fuel_sales
union all select 'SITE-01', 'credit slips', count(*) from public.s01_credit_slips
union all select 'SITE-01', 'customer recoveries', count(*) from public.s01_customer_recoveries
union all select 'SITE-01', 'expenses', count(*) from public.s01_expenses
union all select 'SITE-01', 'tanks', count(*) from public.s01_tanks
union all select 'SITE-01', 'nozzles', count(*) from public.s01_nozzles
union all select 'SITE-01', 'staff advances outstanding (Rs)', (select coalesce(sum(amount), 0) from public.s01_staff_advances where status = 'Outstanding')
union all select 'SITE-01', 'OMC invoices', count(*) from public.s01_omc_invoices
union all select 'SITE-01', 'bank accounts', count(*) from public.s01_bank_accounts
union all
select 'SITE-02'::text as station, 'customers'::text as item, count(*)::numeric as value from public.s02_customers
union all select 'SITE-02', 'customer receivable (Rs)',
  (select coalesce(sum(opening_balance), 0) from public.s02_customers)
  + (select coalesce(sum(total_amount), 0) from public.s02_credit_slips)
  - (select coalesce(sum(amount), 0) from public.s02_customer_recoveries)
union all select 'SITE-02', 'safe cash (Rs)', (select coalesce(sum(cash_in - cash_out), 0) from public.s02_daybook_entries)
union all select 'SITE-02', 'daybook entries', count(*) from public.s02_daybook_entries
union all select 'SITE-02', 'fuel sales', count(*) from public.s02_fuel_sales
union all select 'SITE-02', 'credit slips', count(*) from public.s02_credit_slips
union all select 'SITE-02', 'customer recoveries', count(*) from public.s02_customer_recoveries
union all select 'SITE-02', 'expenses', count(*) from public.s02_expenses
union all select 'SITE-02', 'tanks', count(*) from public.s02_tanks
union all select 'SITE-02', 'nozzles', count(*) from public.s02_nozzles
union all select 'SITE-02', 'staff advances outstanding (Rs)', (select coalesce(sum(amount), 0) from public.s02_staff_advances where status = 'Outstanding')
union all select 'SITE-02', 'OMC invoices', count(*) from public.s02_omc_invoices
union all select 'SITE-02', 'bank accounts', count(*) from public.s02_bank_accounts
union all select 'ALL', 'login accounts', count(*) from public.profiles
) as summary
order by station, item;
